package com.alsafa.native4.core;
import android.content.ContentValues;import android.database.Cursor;import android.database.sqlite.SQLiteDatabase;import com.alsafa.native4.sync.SyncOperation;import org.json.JSONObject;import java.util.UUID;
/** Repair workflow: agreed price remains auditable; final negotiated collection requires explicit confirmation. */
public final class RepairWorkflowStore {private final CoreStore.DbProvider provider;private final String deviceId;public RepairWorkflowStore(CoreStore.DbProvider provider,String deviceId){this.provider=provider;this.deviceId=deviceId;}
 public String receive(String customer,String phone,String watch,double total,String currency,String payment)throws Exception{String c=req(customer,"اسم العميل"),w=req(watch,"وصف الساعة"),cur=MoneyRules.currency(currency),pay=payment(payment);MoneyRules.requirePaymentSupported(pay,cur);if(total<0||!Double.isFinite(total))throw new IllegalArgumentException("المبلغ غير صالح");long now=System.currentTimeMillis();String id="repair-"+UUID.randomUUID(),no="R-"+now;SQLiteDatabase db=provider.db();db.beginTransaction();try{ContentValues v=new ContentValues();v.put("repair_id",id);v.put("invoice_no",no);v.put("customer_name",c);v.put("customer_phone",trim(phone));v.put("watch_description",w);v.put("status","RECEIVED");v.put("total",total);v.put("currency",cur);v.put("payment_method",pay);v.put("received_at",now);v.put("updated_at",now);db.insertOrThrow("repairs",null,v);FxSnapshotStore.Snapshot fx=FxSnapshotStore.capture(db,"REPAIR",id,cur,total,now);enqueue(db,id,no,c,phone,w,"RECEIVED",total,cur,pay,fx,now);db.setTransactionSuccessful();return id;}finally{db.endTransaction();}}
 /** finalNegotiated=true means the agreed price itself is changed; false means any shortage remains due. */
 public Settlement collect(String repairId,double collected,String paymentMethod,String account,boolean finalNegotiated,boolean confirmed,String reason)throws Exception{SQLiteDatabase db=provider.db();db.beginTransaction();try{double agreed;String cur;try(Cursor c=db.rawQuery("SELECT total,currency FROM repairs WHERE repair_id=? AND deleted_at IS NULL",new String[]{repairId})){if(!c.moveToFirst())throw new IllegalArgumentException("الصيانة غير موجودة");agreed=c.getDouble(0);cur=c.getString(1);}if(!Double.isFinite(collected)||collected<0)throw new IllegalArgumentException("المبلغ المحصل غير صالح");String pay=payment(paymentMethod),acc=req(account,"الخزنة").toUpperCase();MoneyRules.requireSupported(acc,cur);MoneyRules.requirePaymentSupported(pay,cur);long now=System.currentTimeMillis();double finalTotal=agreed,balance=Math.max(0,agreed-collected);SettlementAdjustmentStore.Result adj=new SettlementAdjustmentStore.Result(false,0,null);if(finalNegotiated&&Math.abs(collected-agreed)>0.000001){adj=SettlementAdjustmentStore.requireAndWrite(db,"REPAIR",repairId,agreed,collected,cur,confirmed,reason,now);finalTotal=collected;balance=0;ContentValues u=new ContentValues();u.put("total",finalTotal);u.put("updated_at",now);db.update("repairs",u,"repair_id=?",new String[]{repairId});}if(collected>0){java.util.List<SplitPaymentStore.Payment> ps=new java.util.ArrayList<>();ps.add(new SplitPaymentStore.Payment(collected,cur,pay,acc));SplitPaymentStore.write(db,"REPAIR",repairId,ps,now);}JSONObject j=new JSONObject().put("repairId",repairId).put("agreedAmount",agreed).put("collectedAmount",collected).put("finalAmount",finalTotal).put("currency",cur).put("finalNegotiated",finalNegotiated).put("adjustment",adj.difference).put("balanceDue",balance).put("paymentMethod",pay).put("account",acc).put("updatedAt",now);provider.enqueue(db,SyncOperation.create(SyncOperation.Kind.REPAIR,repairId,j.toString(),deviceId));db.setTransactionSuccessful();return new Settlement(agreed,collected,finalTotal,balance,adj.difference,cur);}finally{db.endTransaction();}}
 public void setStatus(String id,String status)throws Exception{String s=trim(status).toUpperCase();if(!s.equals("RECEIVED")&&!s.equals("IN_PROGRESS")&&!s.equals("READY")&&!s.equals("DELIVERED"))throw new IllegalArgumentException("حالة الصيانة غير صالحة");long now=System.currentTimeMillis();SQLiteDatabase db=provider.db();db.beginTransaction();try{ContentValues v=new ContentValues();v.put("status",s);v.put("updated_at",now);if(s.equals("DELIVERED"))v.put("delivered_at",now);if(db.update("repairs",v,"repair_id=? AND deleted_at IS NULL",new String[]{id})!=1)throw new IllegalArgumentException("الصيانة غير موجودة");provider.enqueue(db,SyncOperation.create(SyncOperation.Kind.REPAIR,id,new JSONObject().put("repairId",id).put("status",s).put("updatedAt",now).toString(),deviceId));db.setTransactionSuccessful();}finally{db.endTransaction();}}
 public int addPart(String repairId,String partId,int qty)throws Exception{if(qty<=0)throw new IllegalArgumentException("الكمية غير صالحة");SQLiteDatabase db=provider.db();db.beginTransaction();try{String name;double cost;int before;try(Cursor c=db.rawQuery("SELECT name,cost,quantity FROM repair_part_catalog WHERE part_id=? AND deleted_at IS NULL",new String[]{partId})){if(!c.moveToFirst())throw new IllegalArgumentException("قطعة الصيانة غير موجودة");name=c.getString(0);cost=c.getDouble(1);before=c.getInt(2);}if(before<qty)throw new IllegalArgumentException("رصيد قطعة الصيانة غير كافٍ");long now=System.currentTimeMillis(),dummy=now;int after=before-qty;ContentValues pv=new ContentValues();pv.put("quantity",after);pv.put("updated_at",now);db.update("repair_part_catalog",pv,"part_id=?",new String[]{partId});String item="repairpart-"+UUID.randomUUID();ContentValues iv=new ContentValues();iv.put("item_id",item);iv.put("repair_id",repairId);iv.put("part_id",partId);iv.put("description",name);iv.put("quantity",qty);iv.put("unit_cost",cost);iv.put("created_at",now);db.insertOrThrow("repair_parts",null,iv);provider.enqueue(db,SyncOperation.create(SyncOperation.Kind.REPAIR,repairId,new JSONObject().put("repairId",repairId).put("partId",partId).put("quantity",qty).put("stockAfter",after).put("unitCost",cost).put("updatedAt",now).toString(),deviceId));db.setTransactionSuccessful();return after;}finally{db.endTransaction();}}
 public String quick(String title,double price,String currency,String payment)throws Exception{return receive("عميل صيانة سريعة","",req(title,"نوع الصيانة"),price,currency,payment);}
 private void enqueue(SQLiteDatabase db,String id,String no,String customer,String phone,String watch,String status,double total,String currency,String payment,FxSnapshotStore.Snapshot fx,long now)throws Exception{provider.enqueue(db,SyncOperation.create(SyncOperation.Kind.REPAIR,id,new JSONObject().put("repairId",id).put("invoiceNo",no).put("customerName",customer).put("customerPhone",trim(phone)).put("watchDescription",watch).put("status",status).put("total",total).put("currency",currency).put("paymentMethod",payment).put("fxUsdPerUnit",fx.usdPerUnit).put("totalUsdSnapshot",fx.usdAmount).put("fxCapturedAt",fx.capturedAt).put("updatedAt",now).toString(),deviceId));}
 public static final class Settlement{public final double agreed,collected,finalTotal,balanceDue,adjustment;public final String currency;Settlement(double a,double c,double f,double b,double d,String cur){agreed=a;collected=c;finalTotal=f;balanceDue=b;adjustment=d;currency=cur;}}
 private static String payment(String v){String x=trim(v).toUpperCase();return x.equals("SHAM_CASH")||x.equals("BANK")||x.equals("EXTERNAL")||x.equals("LATER")?x:"CASH";}private static String req(String v,String label){String s=trim(v);if(s.isEmpty())throw new IllegalArgumentException(label+" مطلوب");return s;}private static String trim(String v){return v==null?"":v.trim();}}
